def tensor(*args):
    '''Takes the tensor product of an arbitrary number of matrices/vectors.
    Input:
    args: any number of nd arrays of floats, corresponding to input matrices
    Output:
    M: the tensor product (kronecker product) of input matrices, 2d array of floats
    '''
    if not args:
        return np.array([])

    M = args[0]
    for i in range(1, len(args)):
        M = np.kron(M, args[i])

    # Ensure the output is a 2D array (matrix representation)
    # If the input was a vector (1D), np.kron results in a 1D array.
    # The prompt asks for a 2d array of floats.
    if M.ndim == 1:
        M = M.reshape(-1, 1)
    elif M.ndim == 0:
        M = M.reshape(1, 1)

    return M.astype(float)
